CREATE INDEX `idx_deploy_concluded_latest` ON `deployments` (`platform`,`project_name`,`environment`,`created_at`,`id`) WHERE ((build_phase = 'failed' OR deploy_phase = 'failed' OR ((build_phase IS NULL OR build_phase NOT IN ('canceled', 'unknown')) AND deploy_phase <> 'unknown')) AND ((build_phase IS NULL OR build_phase NOT IN ('building', 'queued')) AND deploy_phase <> 'deploying') AND NOT (build_phase IS NULL AND deploy_phase = 'none'));--> statement-breakpoint
CREATE INDEX `idx_deploy_inflight_latest` ON `deployments` (`platform`,`project_name`,`environment`,`created_at`,`id`) WHERE ((build_phase = 'failed' OR deploy_phase = 'failed' OR ((build_phase IS NULL OR build_phase NOT IN ('canceled', 'unknown')) AND deploy_phase <> 'unknown')) AND ((build_phase IN ('building', 'queued') OR deploy_phase = 'deploying') OR (build_phase IS NULL AND deploy_phase = 'none')));